// Dispatch + structural validation of the built-in modelled library.  Pure C++17.
// (Authors of the instrument renderers do not edit this file.)
#include "ModelLibrary.h"

#include <algorithm>
#include <cmath>
#include <cstdio>
#include <map>
#include <set>

namespace humpire::model
{
namespace
{
struct Expect { const char* instrument; const char* articulation; int swLast; int minVelLayers; int minRoundRobins; };

// Articulations every instrument must provide (see the INSTRUMENT SPECIFICATIONS in ModelLibrary.h).
constexpr Expect kExpect[] = {
    { "mandole",  "pick",    12, 2, 3 }, { "mandole",  "tremolo", 13, 1, 1 },
    { "banjo",    "pick",    12, 2, 2 }, { "banjo",    "roll",    13, 1, 1 },
    { "violon",   "sustain", 12, 2, 1 }, { "violon",   "vibrato", 13, 1, 1 }, { "violon", "pizz", 14, 1, 1 },
    { "ney",      "sustain", 12, 2, 1 }, { "ney",      "breathy", 13, 1, 1 },
    { "qanun",    "pluck",   12, 2, 1 }, { "qanun",    "tremolo", 13, 1, 1 },
    { "derbouka", "dum",     -1, 2, 3 }, { "derbouka", "tek",     -1, 2, 3 }, { "derbouka", "ka", -1, 2, 3 },
    { "derbouka", "slap",    -1, 2, 2 }, { "derbouka", "ghost",   -1, 1, 3 },
    { "tar",      "dum",     -1, 2, 3 }, { "tar",      "tek",     -1, 2, 3 }, { "tar", "ka", -1, 2, 3 },
    { "tar",      "zil",     -1, 2, 3 }, { "tar",      "ghost",   -1, 1, 3 },
    { "bendir",   "dum",     -1, 2, 3 }, { "bendir",   "tek",     -1, 2, 3 }, { "bendir", "ka", -1, 2, 3 },
    { "bendir",   "slap",    -1, 2, 2 }, { "bendir",   "ghost",   -1, 1, 3 }, { "bendir", "roll", -1, 1, 2 },
};

// Percussion lane maps for keys 36..47 (the mirror 48..59 repeats them).
const char* laneFor (int instrument, int key)
{
    static const char* const derb[12] = { "dum", "dum", "tek", "tek", "ka", "slap", "slap", "ghost", "ghost", "tek", "ka", "slap" };
    static const char* const tar [12] = { "dum", "dum", "tek", "tek", "ka", "ka", "zil", "zil", "zil", "ghost", "ghost", "ghost" };
    static const char* const bend[12] = { "dum", "dum", "tek", "tek", "ka", "ka", "slap", "slap", "ghost", "ghost", "roll", "roll" };
    const int k = ((key - 36) % 12 + 12) % 12;
    switch (instrument) { case 5: return derb[k]; case 6: return tar[k]; case 7: return bend[k]; default: return nullptr; }
}

int gcdi (int a, int b) { while (b != 0) { const int t = a % b; a = b; b = t; } return a; }

void pushLimited (std::vector<std::string>& v, std::string s, std::size_t limit = 40)
{
    if (v.size() < limit) v.push_back (std::move (s));
    else if (v.size() == limit) v.push_back ("... further messages suppressed");
}
} // namespace

int findInstrument (const std::string& id)
{
    for (int i = 0; i < kNumModelInstruments; ++i)
        if (id == kSpecs[i].id) return i;
    return -1;
}

Library build (int instrumentIndex, double sampleRate, const std::function<bool (float)>& onProgress)
{
    Library lib;
    if (instrumentIndex < 0 || instrumentIndex >= kNumModelInstruments)
    {
        lib.cancelled = true;
        return lib;
    }

    BuildContext ctx;
    ctx.instrument = instrumentIndex;
    ctx.sampleRate = sampleRate > 1000.0 ? sampleRate : 44100.0;
    ctx.onProgress = onProgress;

    switch (instrumentIndex)
    {
        case 0: lib = buildMandole (ctx); break;
        case 1: lib = buildBanjo (ctx); break;
        case 2: lib = buildViolon (ctx); break;
        case 3: lib = buildNey (ctx); break;
        case 4: lib = buildQanun (ctx); break;
        case 5: lib = buildDerbouka (ctx); break;
        case 6: lib = buildTar (ctx); break;
        default: lib = buildBendir (ctx); break;
    }

    if (lib.instrumentId.empty()) lib.instrumentId = kSpecs[instrumentIndex].id;

    // Last defensive sanitation: never hand NaN / Inf / out-of-range samples to the engine.
    for (auto& z : lib.zones)
        for (auto& s : z.data)
        {
            if (! std::isfinite (s)) s = 0.f;
            else if (s > 0.999f) s = 0.999f;
            else if (s < -0.999f) s = -0.999f;
        }
    return lib;
}

ValidationReport validate (const Library& lib, int idx)
{
    ValidationReport rep;
    auto err = [&] (std::string s) { pushLimited (rep.errors, std::move (s)); };
    auto warn = [&] (std::string s) { pushLimited (rep.warnings, std::move (s)); };

    if (idx < 0 || idx >= kNumModelInstruments) { err ("invalid instrument index"); return rep; }
    const InstrumentSpec& spec = kSpecs[idx];

    if (lib.instrumentId != spec.id) err ("instrumentId is '" + lib.instrumentId + "', expected '" + spec.id + "'");
    if (lib.cancelled) err ("library is marked cancelled");
    if (lib.zones.empty()) { err ("library has no zones"); return rep; }

    const std::size_t bytes = lib.totalFloats() * sizeof (float);
    if (bytes > kMaxLibraryBytes)
        err ("library uses " + std::to_string (bytes / 1024 / 1024) + " MB of float samples (budget " + std::to_string (kMaxLibraryBytes / 1024 / 1024) + " MB)");

    // --- keyswitch configuration
    const bool usesSw = lib.swLo >= 0;
    if (usesSw)
    {
        if (lib.swLo < kKeyswitchLo || lib.swHi > kKeyswitchHi || lib.swHi < lib.swLo)
            err ("keyswitch range must lie inside 12..23");
        if (lib.swDefault < lib.swLo || lib.swDefault > lib.swHi)
            err ("swDefault must lie inside [swLo, swHi]");
    }
    else if (! spec.percussive)
        err ("pitched instruments must declare keyswitches (swLo/swHi/swDefault)");

    std::set<std::string> names;
    std::set<int> switchesUsed;

    for (std::size_t i = 0; i < lib.zones.size(); ++i)
    {
        const Zone& z = lib.zones[i];
        const std::string tag = "zone #" + std::to_string (i) + " '" + z.name + "': ";

        if (z.name.empty()) err (tag + "empty name");
        for (char c : z.name) if (! ((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_' || c == '-')) { err (tag + "name must be [a-z0-9_-]"); break; }
        for (char c : z.articulation) if (! ((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_')) { err (tag + "articulation must be [a-z0-9_]"); break; }
        if (z.articulation.empty()) err (tag + "empty articulation");
        if (! names.insert (z.articulation + "/" + z.name).second) err (tag + "duplicate articulation/name");

        if (z.numChannels < 1 || z.numChannels > 2) { err (tag + "numChannels must be 1 or 2"); continue; }
        if (z.sampleRate < 8000.0 || z.sampleRate > 192000.0) err (tag + "sampleRate out of range");
        if (z.lokey < 0 || z.hikey > 127 || z.lokey > z.hikey) err (tag + "bad key range");
        if (z.keycenter < 0 || z.keycenter > 127) err (tag + "bad keycenter");
        if (z.lovel < 1 || z.hivel > 127 || z.lovel > z.hivel) err (tag + "bad velocity range (must be 1..127)");
        if (z.seqLength < 1 || z.seqLength > 16 || z.seqPosition < 1 || z.seqPosition > z.seqLength) err (tag + "bad seqLength/seqPosition");
        if (z.pan < -100.f || z.pan > 100.f) err (tag + "pan out of range");
        if (z.pitchKeytrack < 0.f || z.pitchKeytrack > 200.f) err (tag + "pitchKeytrack out of range");
        if (z.ampRelease < 0.003f || z.ampRelease > 10.f) err (tag + "ampRelease must be 0.003..10 s");
        if (z.ampAttack < 0.f || z.ampAttack > 5.f || z.ampDecay < 0.f || z.ampSustain < 0.f || z.ampSustain > 100.f) err (tag + "bad amp envelope");
        if (z.ampVeltrack < 0.f || z.ampVeltrack > 100.f) err (tag + "ampVeltrack out of range");
        if (z.group < 0 || z.offBy < 0) err (tag + "negative group/offBy");
        if (z.lokey <= kPhraseHi && z.hikey >= kKeyswitchLo) err (tag + "covers keys inside the keyswitch/phrase area 12..35");
        if (z.swLast >= 0)
        {
            if (! usesSw || z.swLast < lib.swLo || z.swLast > lib.swHi) err (tag + "swLast outside the keyswitch range");
            if (! z.triggerRelease) switchesUsed.insert (z.swLast);
        }
        if (usesSw && ! z.triggerRelease && z.swLast < 0) warn (tag + "swLast = -1: zone sounds in every articulation");
        if (z.triggerRelease)
        {
            if (z.seqLength != 1) err (tag + "release zones must have seqLength 1");
            if (z.loop == Loop::continuous || z.loop == Loop::sustain) err (tag + "release zones must not loop");
        }
        if (spec.percussive)
        {
            if (z.pitchKeytrack != 0.f) warn (tag + "percussion zones should use pitchKeytrack = 0");
            if (z.loop != Loop::oneShot) warn (tag + "percussion zones should use Loop::oneShot");
        }
        else if (! z.triggerRelease && z.pitchKeytrack != 100.f && z.pitchKeytrack != 0.f)
            warn (tag + "unusual pitchKeytrack");

        // --- audio ownership
        const Zone* owner = &z;
        if (z.sharedWith >= 0)
        {
            if ((std::size_t) z.sharedWith >= i) { err (tag + "sharedWith must refer to a lower zone index"); continue; }
            owner = &lib.zones[(std::size_t) z.sharedWith];
            if (owner->sharedWith >= 0) { err (tag + "alias of an alias"); continue; }
            if (! z.data.empty()) err (tag + "alias zone must not own data");
            if (owner->numChannels != z.numChannels || owner->sampleRate != z.sampleRate) err (tag + "alias must copy channel count and sample rate");
            if (owner->loop != z.loop || owner->loopStart != z.loopStart || owner->loopEnd != z.loopEnd) err (tag + "alias must copy loop mode and loop points");
        }
        else
        {
            if (z.data.empty()) { err (tag + "no audio data"); continue; }
            if (z.data.size() % (std::size_t) z.numChannels != 0) { err (tag + "data size not a multiple of numChannels"); continue; }
        }

        if (z.sharedWith >= 0) continue;                         // audio checks are done on the owner

        const std::size_t frames = z.numFrames();
        if (frames < 64) err (tag + "fewer than 64 frames");
        float peak = 0.f;
        bool finite = true;
        for (float s : z.data) { if (! std::isfinite (s)) { finite = false; break; } peak = std::max (peak, std::fabs (s)); }
        if (! finite) { err (tag + "contains NaN/Inf"); continue; }
        if (peak > 1.0f) err (tag + "peak exceeds 0 dBFS");
        else if (peak > 0.891f) warn (tag + "peak above -1 dBFS");
        if (peak < 0.01f) warn (tag + "peak below -40 dBFS (practically silent)");
        if (std::fabs (z.data.front()) > 0.01f) warn (tag + "first frame is not near zero (click at start)");

        if (z.loop == Loop::continuous || z.loop == Loop::sustain)
        {
            const long long ls = z.loopStart, le = z.loopEnd;
            if (ls < 0 || le <= ls + 32 || (std::size_t) le + 3 >= frames)
                err (tag + "invalid loop points (need 0 <= loopStart, loopEnd > loopStart + 32 and >= 3 guard frames after loopEnd; use finishLoop)");
            else
            {
                const std::size_t ch = (std::size_t) z.numChannels;
                bool guardOk = true;
                for (std::size_t g = 0; g < 3 && guardOk; ++g)
                    for (std::size_t c = 0; c < ch; ++c)
                        if (std::fabs (z.data[((std::size_t) le + 1 + g) * ch + c] - z.data[((std::size_t) ls + g) * ch + c]) > 1.0e-6f) guardOk = false;
                if (! guardOk) err (tag + "loop guard frames after loopEnd must repeat the frames at loopStart (use finishLoop)");

                // seam step vs typical step
                double d2 = 0.0;
                std::size_t cnt = 0;
                for (long long k = ls + 1; k <= le; ++k) { const double d = (double) z.data[(std::size_t) k * ch] - (double) z.data[(std::size_t) (k - 1) * ch]; d2 += d * d; ++cnt; }
                const double rmsStep = std::sqrt (d2 / (double) std::max<std::size_t> (cnt, 1));
                const double seam = std::fabs ((double) z.data[(std::size_t) ls * ch] - (double) z.data[(std::size_t) le * ch]);
                if (seam > 15.0 * rmsStep + 0.01) err (tag + "loop seam is discontinuous (jump " + std::to_string (seam) + ")");
                else if (seam > 6.0 * rmsStep + 0.003) warn (tag + "loop seam jump is larger than the local signal step");
            }
        }
        else if (z.loop == Loop::none && ! z.triggerRelease && std::fabs (z.data.back()) > 0.002f)
            warn (tag + "last frame is not faded to zero (click at end)");
    }
    if (! rep.ok()) return rep;                                  // coverage checks need sane zones

    // --- required articulations: velocity layers, round robins, keyswitch numbers
    for (const auto& e : kExpect)
    {
        if (std::string (e.instrument) != spec.id) continue;
        std::set<std::pair<int, int>> layers;
        int maxRR = 1, swSeen = -2;
        bool any = false;
        for (const auto& z : lib.zones)
        {
            if (z.articulation != e.articulation || z.triggerRelease) continue;
            any = true;
            layers.insert ({ z.lovel, z.hivel });
            maxRR = std::max (maxRR, z.seqLength);
            if (swSeen == -2) swSeen = z.swLast;
        }
        const std::string a = e.articulation;
        if (! any) { err ("missing required articulation '" + a + "'"); continue; }
        if ((int) layers.size() < e.minVelLayers) err ("articulation '" + a + "' needs >= " + std::to_string (e.minVelLayers) + " velocity layer(s), has " + std::to_string (layers.size()));
        if (maxRR < e.minRoundRobins) err ("articulation '" + a + "' needs " + std::to_string (e.minRoundRobins) + " round robins (seqLength), has " + std::to_string (maxRR));
        if (e.swLast >= 0 && swSeen != e.swLast) err ("articulation '" + a + "' must use keyswitch " + std::to_string (e.swLast) + " (sw_last)");
    }
    if (std::string (spec.id) == "violon")
    {
        std::set<int> rel;
        for (const auto& z : lib.zones) if (z.triggerRelease) rel.insert (z.swLast);
        if (rel.count (12) == 0 || rel.count (13) == 0) err ("violon needs 'bowlift' release-trigger zones for keyswitch 12 and 13");
    }

    // --- coverage: every key of the range, every velocity, every round-robin step, every articulation
    std::set<int> articulations;
    if (usesSw)
    {
        for (int s : switchesUsed) articulations.insert (s);
        if (articulations.empty()) articulations.insert (lib.swDefault);
        if (articulations.count (lib.swDefault) == 0) err ("no zone belongs to the default articulation (swDefault)");
    }
    else articulations.insert (-1);

    int period = 1;
    for (const auto& z : lib.zones) period = std::min (60, period / gcdi (period, z.seqLength) * z.seqLength);

    std::size_t covReported = 0, ovlReported = 0;
    for (int art : articulations)
        for (int key = spec.lo; key <= spec.hi; ++key)
        {
            // candidate zones for this key
            std::vector<const Zone*> cand;
            for (const auto& z : lib.zones)
                if (! z.triggerRelease && key >= z.lokey && key <= z.hikey && (z.swLast < 0 || z.swLast == art)) cand.push_back (&z);

            for (int vel = 1; vel <= 127; ++vel)
                for (int rr = 0; rr < period; ++rr)
                {
                    int n = 0;
                    const Zone* first = nullptr;
                    for (const Zone* z : cand)
                        if (zoneMatches (*z, key, vel, rr, art, false)) { if (n++ == 0) first = z; }
                    if (n == 0 && covReported < 12)
                    {
                        ++covReported;
                        err ("no zone for key " + std::to_string (key) + " vel " + std::to_string (vel) + " rr-step " + std::to_string (rr) + " articulation " + std::to_string (art));
                    }
                    else if (n > 1 && ovlReported < 12)
                    {
                        ++ovlReported;
                        err (std::to_string (n) + " zones overlap at key " + std::to_string (key) + " vel " + std::to_string (vel) + " rr-step " + std::to_string (rr)
                             + " articulation " + std::to_string (art) + " (first: '" + first->name + "')");
                    }
                }
        }

    // --- percussion lane map
    if (spec.percussive)
    {
        for (int key = 36; key <= 59; ++key)
        {
            const char* want = laneFor (idx, key);
            const Zone* hit = nullptr;
            for (const auto& z : lib.zones)
                if (! z.triggerRelease && key >= z.lokey && key <= z.hikey && z.hivel >= 100 && z.lovel <= 100) { hit = &z; break; }
            if (hit != nullptr && want != nullptr && hit->articulation != want)
                err ("key " + std::to_string (key) + " should play lane '" + want + "', but plays '" + hit->articulation + "'");
        }
    }
    return rep;
}
} // namespace humpire::model
